// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testRegression_property() public {
        address payable owner = payable(address(this));
        address nonOwner = address(1);

        vm.prank(owner);
        c.mintToken(nonOwner, 100);

        uint256 balanceBefore = c.balanceOf(nonOwner);

        vm.prank(nonOwner);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", 10));

        uint256 balanceAfter = c.balanceOf(nonOwner);

        assertTrue(balanceBefore == balanceAfter, "Balance should remain unchanged if burn reverts");
    }
}
